<template><view :class="['app-page',{dark}]"><ui-header title="提现详情" back/><view v-if="detail" class="detail-card"><view class="result"><ui-icon :name="detail.status==='rejected'?'x':'wallet'" :size="66"/><text class="price">¥{{money(detail.amount)}}</text><text>{{status(detail.status)}}</text></view><view class="rows"><view><text>提现单号</text><text>{{detail.withdrawalNo}}</text></view><view><text>申请时间</text><text>{{displayDateTime(detail.createdAt)}}</text></view><view><text>审核时间</text><text>{{detail.reviewedAt?displayDateTime(detail.reviewedAt):'待审核'}}</text></view><view><text>审核说明</text><text>{{detail.reviewNote||'暂无'}}</text></view></view><view v-if="detail.records&&detail.records.length" class="flow"><text class="section-title">资金流水</text><view v-for="item in detail.records" :key="item.id"><text>{{item.description}}</text><text>{{displayDateTime(item.createdAt)}}</text></view></view></view><ui-page-status v-else :loading="loading" :description="error" @retry="load"/></view></template>
<script>import{api}from'@/services/api';import{isDark}from'@/utils/app';export default{data(){return{dark:false,id:'',loading:true,error:'',detail:null}},onLoad(q){this.dark=isDark();this.id=q.id||'';this.load()},methods:{money(v){return Number(v||0).toFixed(2)},status(v){return({pending:'审核中',approved:'已通过',rejected:'已驳回',paid:'已完成'})[v]||v},async load(){this.loading=true;this.error='';try{this.detail=await api.getWithdrawal(this.id)}catch(e){this.detail=null;this.error=e.message||'提现详情加载失败'}finally{this.loading=false}}}}</script>
<style scoped>.detail-card{margin:28rpx;padding:30rpx;border-radius:26rpx;background:var(--surface);box-shadow:var(--shadow-card)}.result{padding:20rpx 0 34rpx;display:flex;flex-direction:column;align-items:center;gap:12rpx}.result .price{font-size:44rpx}.rows>view{min-height:82rpx;display:flex;align-items:center;justify-content:space-between;border-bottom:1rpx solid var(--line);font-size:23rpx}.rows>view>text:first-child{color:var(--muted)}.rows>view>text:last-child{max-width:420rpx;text-align:right}.flow{margin-top:28rpx}.flow>view{padding:18rpx 0;display:flex;justify-content:space-between;border-bottom:1rpx solid var(--line);color:var(--muted);font-size:21rpx}</style>
